import urllib.parse,uuid

def audit_resources(base_url,expected,visible,fetch):
    def normalized(values):
        out=[str(uuid.UUID(value)) for value in values]
        if len(out)!=len(set(out)):raise ValueError('duplicate subscription ID')
        return set(out)
    wanted=normalized(expected);accessible=normalized(visible)
    base=urllib.parse.urlsplit(base_url)
    if base.scheme not in ('http','https') or not base.netloc or base.username or base.password or base.query or base.fragment:raise ValueError('explicit trusted endpoint origin required')
    result={'complete':True,'scope':'expected-subscriptions-generic-arm-resources-only','subscriptions':[],'resources':[],'unexpected_visible':sorted(accessible-wanted)}
    for subscription in sorted(wanted):
        if subscription not in accessible:
            result['complete']=False
            result['subscriptions'].append({'id':subscription,'status':'missing','resource_count':0})
            continue
        path=base.path.rstrip('/')+'/subscriptions/'+subscription+'/resources'
        url=urllib.parse.urlunsplit((base.scheme,base.netloc,path,'api-version=2021-04-01',''))
        visited=set();resources={}
        try:
            while url is not None:
                part=urllib.parse.urlsplit(url)
                if (part.scheme,part.netloc,part.path)!=(base.scheme,base.netloc,path) or part.username or part.password or part.fragment:raise ValueError('out-of-scope continuation')
                if url in visited or len(visited)>=100:raise ValueError('cyclic or over-budget pagination')
                visited.add(url)
                code,page=fetch(url)
                if code!=200:raise ValueError('resource listing failed: '+str(code))
                if not isinstance(page,dict) or not isinstance(page.get('value'),list):raise ValueError('malformed list page')
                for resource in page['value']:
                    if not isinstance(resource,dict) or not isinstance(resource.get('id'),str):raise ValueError('resource ID missing')
                    key=resource['id'].lower()
                    if not key.startswith('/subscriptions/'+subscription+'/resourcegroups/') or '/providers/' not in key:raise ValueError('cross-subscription or unsupported resource identity')
                    if key in resources and resources[key]!=resource:raise ValueError('conflicting duplicate resource identity')
                    resources[key]=dict(resource)
                next_link=page.get('nextLink')
                if next_link is not None and (not isinstance(next_link,str) or not next_link):raise ValueError('invalid continuation')
                url=next_link
            result['subscriptions'].append({'id':subscription,'status':'complete','resource_count':len(resources)})
            result['resources'].extend(resources[key] for key in sorted(resources))
        except (TimeoutError,ValueError,KeyError,TypeError):
            result['complete']=False
            result['subscriptions'].append({'id':subscription,'status':'failed','resource_count':0})
    result['resources'].sort(key=lambda resource:resource['id'].lower())
    return result
